M11 = module(11, "m11", "Основи відеозйомки", "4K/FHD, FPS, PAL/NTSC, правило 180°, кроп, кодеки, AF, звук, S-Cinetone/S-Log3, S&Q та готові налаштування.", "".join(m11))

